        public int read(int at)throws IOException{return readInt(at);}
        public void write(int at,int value)throws IOException{writeInt(at,value);}
        public int readInt(int at)throws IOException{int v=0;for(int n=0;n<4;n++)v|=readByte(at+n)<<(n*8);return v;}
        public void writeByte(int at,int v)throws IOException{if(glyphMemory!=null&&glyphMemory.ownsAddress(at)){glyphMemory.writeByte(at,v);return;}byte[] r=region(at);r[at-raw.floorKey(at)]=(byte)v;}
        public void writeInt(int at,int v)throws IOException{for(int n=0;n<4;n++)readByte(at+n);for(int n=0;n<4;n++)writeByte(at+n,v>>>(n*8));}
