        public void freeImage(int handle)throws IOException{events.add("free,"+handle);mutateResource("free");}
        private void mutateResource(String name)throws IOException{int[][] w=spriteWrites.get(name);if(w!=null)for(int[] a:w)writeInt(a[0],a[1]);}
        public void ensureTimer5(){events.add("timer5");}
        private void sprite(String name,Integer argument)throws IOException{events.add(name+(argument==null?"":","+argument));int[][] w=spriteWrites.get(name);if(w!=null)for(int[] a:w)writeInt(a[0],a[1]);}
